// 真实跑起来：node:http 起服务（随机高位端口）→ 内置 fetch 自请求 → 打印状态码与响应体
const http = require('http');

const db = new Map();
let nextId = 1;
function create(input) {
  const id = String(nextId++);
  const item = { id, title: input.title, tags: input.tags || [], status: 'draft' };
  db.set(id, item);
  return item;
}
create({ title: 'intro to sql', tags: ['sql'] });
create({ title: 'rest design', tags: [] });

// 极简 schema 校验：title 必填 string 1..40；tags 可选 string[]
function validate(body) {
  const errs = [];
  if (typeof body !== 'object' || body === null || Array.isArray(body)) return ['body: must be object'];
  if (typeof body.title !== 'string') errs.push('title: required string');
  else if (body.title.length < 1 || body.title.length > 40) errs.push('title: length must be 1..40');
  if (body.tags !== undefined && (!Array.isArray(body.tags) || body.tags.some(t => typeof t !== 'string')))
    errs.push('tags: must be string[]');
  return errs;
}

function send(res, status, payload, headers) {
  const h = Object.assign({}, headers || {});
  if (status === 204) { res.writeHead(204, h); res.end(); return; }
  const text = JSON.stringify(payload);
  h['content-type'] = 'application/json; charset=utf-8';
  h['content-length'] = Buffer.byteLength(text);
  res.writeHead(status, h);
  res.end(text);
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, 'http://127.0.0.1');
  const parts = url.pathname.split('/').filter(Boolean);

  if (parts[0] !== 'articles') return send(res, 404, { title: 'Not Found', status: 404 });

  if (parts.length === 1) {
    if (req.method === 'GET') {
      const raw = url.searchParams.get('limit');
      const limit = raw === null ? 10 : Math.min(Number(raw), 50);
      return send(res, 200, { data: [...db.values()].slice(0, limit), total: db.size });
    }
    if (req.method === 'POST') {
      let raw = '';
      req.on('data', c => { raw += c; });
      req.on('end', () => {
        let body;
        try { body = JSON.parse(raw); } catch (e) { return send(res, 400, { title: 'Malformed JSON', status: 400 }); }
        const errs = validate(body);
        if (errs.length) return send(res, 422, { title: 'Validation Failed', status: 422, errors: errs });
        const item = create(body);
        return send(res, 201, item, { location: '/articles/' + item.id });
      });
      return;
    }
    return send(res, 405, { title: 'Method Not Allowed', status: 405 }, { allow: 'GET, POST' });
  }

  if (parts.length === 2) {
    const id = parts[1];
    if (req.method === 'GET') {
      if (!db.has(id)) return send(res, 404, { title: 'Not Found', status: 404 });
      return send(res, 200, db.get(id));
    }
    if (req.method === 'DELETE') {
      if (!db.has(id)) return send(res, 404, { title: 'Not Found', status: 404 });
      db.delete(id);
      return send(res, 204);
    }
    return send(res, 405, { title: 'Method Not Allowed', status: 405 }, { allow: 'GET, DELETE' });
  }
  return send(res, 404, { title: 'Not Found', status: 404 });
});

async function call(base, method, path, body) {
  const opts = { method, headers: {} };
  if (body !== undefined) { opts.body = JSON.stringify(body); opts.headers['content-type'] = 'application/json'; }
  const r = await fetch(base + path, opts);
  const text = await r.text();
  return {
    status: r.status,
    ct: (r.headers.get('content-type') || '-').split(';')[0],
    loc: r.headers.get('location') || '-',
    allow: r.headers.get('allow') || '-',
    body: text === '' ? null : JSON.parse(text),
  };
}

server.listen(0, '127.0.0.1', async () => {
  const base = 'http://127.0.0.1:' + server.address().port;
  const cases = [
    ['GET', '/articles', undefined],
    ['GET', '/articles/1', undefined],
    ['GET', '/articles/999', undefined],
    ['POST', '/articles', { title: 'index basics', tags: ['db'] }],
    ['POST', '/articles', { tags: [] }],
    ['GET', '/articles?limit=1', undefined],
    ['PUT', '/articles/2', {}],
    ['DELETE', '/articles/1', undefined],
    ['DELETE', '/articles/1', undefined],
    ['GET', '/users', undefined],
  ];
  const lines = [];
  for (const [m, p, b] of cases) {
    const r = await call(base, m, p, b);
    lines.push('req ' + (m + ' ' + p).padEnd(22) + 'status=' + String(r.status).padEnd(4)
      + 'ct=' + r.ct.padEnd(17) + 'loc=' + r.loc.padEnd(12) + 'allow=' + r.allow.padEnd(11)
      + 'body=' + JSON.stringify(r.body));
  }
  const bad = await fetch(base + '/articles', {
    method: 'POST', headers: { 'content-type': 'application/json' }, body: '{oops',
  });
  lines.push('req POST /articles (raw "{oops")  status=' + bad.status
    + '  body=' + JSON.stringify(await bad.json()));
  console.log(lines.join('\n'));
  server.close();
});
